// Portable run loop: emulator core + platform interface + built-in programs.
// Nothing in here knows whether it's running on a desktop or a microcontroller.
//
// With one program built in, it runs straight away. With several, a menu comes
// first (keypad 2 / 8 to move, 5 to run), and the MENU button comes back to it.

#include "chip8.h"
#include "frame_clock.h"
#include "key_gate.h"
#include "menu.h"
#include "platform.h"
#include "roms.h"  // generated by tools/make_roms.py: kRoms[], kRomCount

namespace {

// Instructions per 60 Hz frame; 12 is about 720 per second. A board build can
// change it with -DCHIP8_CYCLES_PER_FRAME=N.
#ifndef CHIP8_CYCLES_PER_FRAME
#define CHIP8_CYCLES_PER_FRAME 12
#endif
constexpr int kCyclesPerFrame = CHIP8_CYCLES_PER_FRAME;

// The MENU button has to be held this many frames (about 0.2 s), so a bump
// doesn't throw you out of a game.
constexpr int kMenuHoldFrames = 12;

// Static, not on the stack: these are several KB, and a microcontroller's
// stack is typically 2 KB or less (the Pico's default).
Chip8 chip8;
uint8_t menuPixels[Menu::kWidth * Menu::kHeight];

}  // namespace

int main() {
    platform::init();

    Menu menu(kRoms, kRomCount);
    KeyGate gate;
    FrameClock clock(platform::millisNow());

    bool inMenu = kRomCount > 1;
    bool halted = false;  // set when the core hits an opcode it can't run
    int menuHeld = 0;     // frames the MENU button has been down

    auto launch = [&](int index, uint16_t keysNow) {
        chip8.reset();
        chip8.seedRandom(platform::randomSeed());
        // A ROM that doesn't fit is a build-time error (make_roms.py checks), so
        // this can only fail if the table is wrong; show an empty screen then.
        halted = !chip8.loadRom(kRoms[index].data, kRoms[index].size);
        gate.begin(keysNow);
        inMenu = false;
        platform::setBuzzer(false);
    };

    uint16_t keys = platform::readKeys();
    if (inMenu) {
        menu.open(keys);
    } else {
        launch(0, keys);
    }
    int current = inMenu ? -1 : 0;

    while (platform::keepRunning()) {
        keys = platform::readKeys();
        menuHeld = platform::menuButton() ? menuHeld + 1 : 0;
        const bool menuPressed = menuHeld == kMenuHoldFrames;  // once per press

        if (inMenu) {
            const int pick = menu.update(keys);
            menu.render(menuPixels);
            platform::drawFrame(menuPixels, Menu::kWidth, Menu::kHeight);
            if (pick >= 0) {
                current = pick;
                launch(pick, keys);
            }
        } else if (menuPressed) {
            if (kRomCount > 1) {
                inMenu = true;
                platform::setBuzzer(false);
                menu.open(keys);
            } else {
                launch(current, keys);  // one program: the button restarts it
            }
        } else {
            const uint16_t visible = gate.filter(keys);
            for (int k = 0; k < 16; ++k) {
                chip8.keypad[k] = (visible >> k) & 1;
            }

            if (!halted) {
                for (int c = 0; c < kCyclesPerFrame; ++c) {
                    if (!chip8.cycle()) {
                        halted = true;
                        break;
                    }
                }
                chip8.tickTimers();
            }

            platform::setBuzzer(chip8.soundTimer > 0);
            platform::drawFrame(chip8.display.data(), Chip8::kDisplayWidth,
                                Chip8::kDisplayHeight);
        }

        const uint32_t wait = clock.msUntilNextFrame(platform::millisNow());
        if (wait > 0) {
            platform::sleepMs(wait);
        }
    }
    return 0;
}
